{!REQUIRESCRIPT("/soap/ajax/15.0/connection.js")} 
{!REQUIRESCRIPT("/soap/ajax/15.0/apex.js")} 
var currencycode = sforce.connection.query("select id,DefaultCurrencyIsoCode from User where id='{!$User.Id}'"); 
//alert(currencycode.records.DefaultCurrencyIsoCode); 
if(currencycode.records.DefaultCurrencyIsoCode== 'EUR'){ 
var rep = '/00O34000005etjt?pv0={!SUBSTITUTE(BoB_Coverage__c.Sales_Rep_Name__c, "'", "\'")}&pv1={!SUBSTITUTE(TEXT(BoB_Coverage__c.Sales_Rep_Role__c), "'", "\'")}'; 
parent.location.href =rep; 
}else{ 
var rep1 = '/00O340000064qcW?pv0={!SUBSTITUTE(BoB_Coverage__c.Sales_Rep_Name__c, "'", "\'")}&pv1={!SUBSTITUTE(TEXT(BoB_Coverage__c.Sales_Rep_Role__c), "'", "\'")}'; 
parent.location.href =rep1; 
}
